:root{--neo-green:var(--clr-primary,#0F4C23);--neo-accent:var(--clr-accent,#C9A45C);--neo-secondary:var(--clr-secondary,#2E7D45);--neo-cream:var(--clr-bg,#F7F8F4);--neo-ink:var(--clr-text,#18231B);--neo-muted:var(--clr-text-light,#69756C);--neo-shadow:0 28px 70px rgba(15,76,35,.16);--neo-radius:28px}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{overflow-x:hidden;background:var(--neo-cream);font-family:'Tajawal',sans-serif;color:var(--neo-ink)}a{text-decoration:none}img{max-width:100%;display:block}.container{width:min(1220px,calc(100% - 40px));margin-inline:auto}.lang-en{font-family:Inter,sans-serif}.neo-topline{height:5px;background:linear-gradient(90deg,var(--neo-green),var(--neo-accent),var(--neo-green))}
/* Navigation */
.neo-nav{position:sticky;top:0;z-index:1000;background:rgba(250,251,248,.86);backdrop-filter:blur(18px);border-bottom:1px solid rgba(15,76,35,.09);transition:box-shadow .3s}.neo-nav.scrolled{box-shadow:0 12px 35px rgba(15,76,35,.12)}.neo-nav-inner{min-height:84px;display:flex;align-items:center;justify-content:space-between;gap:24px}.neo-logo img{height:58px;width:auto;filter:drop-shadow(0 8px 10px rgba(15,76,35,.13));transition:transform .4s}.neo-logo:hover img{transform:translateY(-3px) rotate(-3deg)}.neo-links{display:flex;align-items:center;gap:clamp(14px,2vw,30px)}.neo-links a{color:var(--neo-green);font-weight:800;position:relative;padding:10px 0}.neo-links a:after{content:'';position:absolute;bottom:2px;right:0;width:0;height:3px;border-radius:9px;background:var(--neo-accent);transition:width .3s}.neo-links a:hover:after,.neo-links a.active:after{width:100%}.neo-nav-tools{display:flex;gap:10px;align-items:center}.neo-lang,.neo-menu{border:1px solid rgba(15,76,35,.16);background:white;color:var(--neo-green);border-radius:14px;padding:11px 16px;font:inherit;font-weight:800;cursor:pointer;transition:.25s}.neo-lang:hover,.neo-menu:hover{transform:translateY(-3px);box-shadow:0 10px 22px rgba(15,76,35,.13)}.neo-menu{display:none;padding:9px 12px}
/* Hero */
.neo-hero{position:relative;isolation:isolate;min-height:min(760px,calc(100vh - 84px));display:flex;align-items:center;overflow:hidden;background:var(--neo-green);color:#fff}.neo-hero-slides,.neo-hero-slide,.neo-hero-shade{position:absolute;inset:0}.neo-hero-slide{opacity:0;transition:opacity 1.2s ease;overflow:hidden}.neo-hero-slide.active{opacity:1}.neo-hero-slide img{width:100%;height:100%;object-fit:cover;transform:scale(1.08);animation:heroZoom 10s ease-in-out infinite alternate}.neo-hero-shade{background:linear-gradient(90deg,rgba(7,35,16,.76),rgba(15,76,35,.82) 48%,rgba(15,76,35,.46));z-index:1}.neo-orb{position:absolute;z-index:2;pointer-events:none;border-radius:50%;filter:blur(1px);border:1px solid rgba(255,255,255,.23);box-shadow:inset 0 0 40px rgba(255,255,255,.06),0 20px 80px rgba(0,0,0,.13);animation:orbFloat 8s ease-in-out infinite}.neo-orb.one{width:330px;height:330px;left:5%;top:10%;background:radial-gradient(circle at 30% 25%,rgba(255,255,255,.23),rgba(255,255,255,.015) 65%);}.neo-orb.two{width:170px;height:170px;left:27%;bottom:10%;animation-delay:-3s;background:radial-gradient(circle at 35% 25%,rgba(201,164,92,.3),transparent 70%)}.neo-hero-inner{position:relative;z-index:3;width:100%;padding-block:100px;display:grid;grid-template-columns:1.15fr .85fr;gap:50px;align-items:center}.neo-kicker{display:inline-flex;align-items:center;gap:10px;border:1px solid rgba(255,255,255,.35);border-radius:99px;padding:9px 15px;background:rgba(255,255,255,.08);backdrop-filter:blur(10px);font-weight:700;letter-spacing:.3px;animation:riseIn .8s both}.neo-kicker:before{content:'';width:8px;height:8px;border-radius:50%;background:var(--neo-accent);box-shadow:0 0 18px var(--neo-accent)}.neo-hero h1{font-size:clamp(2.8rem,5.6vw,5.6rem);line-height:1.13;letter-spacing:-1.5px;margin:25px 0 20px;font-weight:900;text-wrap:balance;animation:riseIn .8s .1s both}.neo-hero h1 em{font-style:normal;color:var(--neo-accent);display:inline-block;text-shadow:0 10px 35px rgba(0,0,0,.17)}.neo-hero-copy{max-width:610px;color:rgba(255,255,255,.85);font-size:clamp(1.05rem,1.5vw,1.25rem);line-height:2;margin:0;animation:riseIn .8s .2s both}.neo-hero-actions{display:flex;flex-wrap:wrap;gap:14px;margin-top:32px;animation:riseIn .8s .3s both}.neo-btn{display:inline-flex;justify-content:center;align-items:center;gap:12px;padding:15px 24px;border-radius:15px;font-weight:900;transition:transform .3s,box-shadow .3s;background:var(--neo-accent);color:#172519;box-shadow:0 12px 0 rgba(0,0,0,.12),0 22px 36px rgba(0,0,0,.18);transform:translateY(0)}.neo-btn:hover{transform:translateY(-6px);box-shadow:0 18px 0 rgba(0,0,0,.08),0 28px 40px rgba(0,0,0,.22)}.neo-btn.ghost{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.38);color:white;box-shadow:none;backdrop-filter:blur(10px)}.neo-hero-visual{min-height:400px;position:relative;display:grid;place-items:center;perspective:1000px}.neo-glass-card{width:min(390px,88%);aspect-ratio: .84;position:relative;border:1px solid rgba(255,255,255,.35);border-radius:34px;padding:14px;background:linear-gradient(145deg,rgba(255,255,255,.26),rgba(255,255,255,.06));box-shadow:0 35px 90px rgba(0,0,0,.3),inset 0 1px 0 rgba(255,255,255,.45);backdrop-filter:blur(14px);transform:rotateY(-12deg) rotateX(5deg);animation:cardLevitate 6s ease-in-out infinite}.neo-glass-card:before{content:'';position:absolute;inset:14px;border-radius:24px;border:1px solid rgba(255,255,255,.22);pointer-events:none}.neo-glass-inner{height:100%;border-radius:24px;overflow:hidden;position:relative;background:rgba(255,255,255,.08)}.neo-glass-inner img{height:100%;width:100%;object-fit:cover;opacity:.92}.neo-glass-caption{position:absolute;bottom:16px;right:16px;left:16px;padding:18px;border-radius:20px;color:white;background:rgba(15,76,35,.78);border:1px solid rgba(255,255,255,.22);backdrop-filter:blur(12px)}.neo-glass-caption small{display:block;color:var(--neo-accent);font-weight:800;margin-bottom:4px}.neo-glass-caption strong{font-size:1.4rem}.neo-float-chip{position:absolute;z-index:2;padding:14px 18px;border-radius:18px;background:#fff;color:var(--neo-green);box-shadow:0 20px 45px rgba(0,0,0,.22);font-weight:900;animation:orbFloat 5s ease-in-out infinite}.neo-float-chip.top{top:8%;right:-1%}.neo-float-chip.bottom{bottom:9%;left:-3%;animation-delay:-2s}.neo-float-chip span{display:block;font-size:.8rem;color:var(--neo-muted);font-weight:600}.neo-slider-dots{position:absolute;z-index:4;bottom:26px;right:50%;transform:translateX(50%);display:flex;gap:8px}.neo-slider-dots button{width:9px;height:9px;border:0;border-radius:20px;background:rgba(255,255,255,.45);cursor:pointer;transition:.3s;padding:0}.neo-slider-dots button.active{width:30px;background:var(--neo-accent)}
/* floating trust strip */
.neo-trust-wrap{position:relative;z-index:5;margin-top:-34px}.neo-trust{display:grid;grid-template-columns:repeat(3,1fr);background:#fff;border:1px solid rgba(15,76,35,.08);border-radius:24px;box-shadow:var(--neo-shadow);overflow:hidden}.neo-trust-item{display:flex;align-items:center;justify-content:center;gap:14px;padding:24px 18px}.neo-trust-item+.neo-trust-item{border-right:1px solid rgba(15,76,35,.09)}.neo-trust-icon{width:48px;height:48px;flex:0 0 48px;display:grid;place-items:center;border-radius:16px;background:var(--neo-cream);color:var(--neo-green);font-size:1.35rem}.neo-trust strong{display:block;color:var(--neo-green);font-size:1.05rem}.neo-trust small{color:var(--neo-muted)}
/* section framework */
.neo-section{padding:105px 0;position:relative}.neo-section-head{display:flex;align-items:end;justify-content:space-between;gap:25px;margin-bottom:42px}.neo-eyebrow{display:inline-block;color:var(--neo-secondary);font-weight:900;font-size:.9rem;letter-spacing:1px;margin-bottom:10px}.neo-section h2{font-size:clamp(2rem,4vw,3.45rem);line-height:1.2;color:var(--neo-green);margin:0;font-weight:900}.neo-section-head p{max-width:480px;line-height:1.9;color:var(--neo-muted);margin:12px 0 0}.neo-text-link{color:var(--neo-green);font-weight:900;white-space:nowrap;border-bottom:2px solid var(--neo-accent);padding-bottom:7px}.neo-text-link:hover{color:var(--neo-secondary)}
/* categories */
.neo-categories{background:var(--neo-cream);overflow:hidden}.neo-category-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:22px;perspective:1200px}.neo-category{position:relative;min-height:330px;border-radius:var(--neo-radius);overflow:hidden;isolation:isolate;box-shadow:0 18px 40px rgba(15,76,35,.1);transform-style:preserve-3d;transition:transform .45s cubic-bezier(.2,.8,.2,1),box-shadow .45s;border:1px solid rgba(255,255,255,.7)}.neo-category:hover{transform:translateY(-12px) rotateX(3deg) rotateY(-3deg);box-shadow:0 35px 65px rgba(15,76,35,.2)}.neo-category img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform .8s cubic-bezier(.2,.8,.2,1)}.neo-category:hover img{transform:scale(1.12)}.neo-category:after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,transparent 25%,rgba(6,32,14,.18) 45%,rgba(6,32,14,.9));z-index:1}.neo-category-content{position:absolute;z-index:2;bottom:0;right:0;left:0;padding:25px;color:#fff;transform:translateZ(35px)}.neo-category-content h3{font-size:1.5rem;margin:0 0 7px;font-weight:900}.neo-category-content span{display:inline-flex;align-items:center;gap:8px;color:rgba(255,255,255,.84);font-size:.9rem}.neo-category-content span:after{content:'←';color:var(--neo-accent);font-size:1.2rem;transition:transform .3s}.neo-category:hover .neo-category-content span:after{transform:translateX(-5px)}
/* products */
.neo-products{background:#fff;overflow:hidden}.neo-products:before{content:'';position:absolute;width:420px;height:420px;border-radius:50%;background:rgba(15,76,35,.035);top:8%;left:-180px;filter:blur(2px)}.neo-product-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:22px;perspective:1300px}.neo-product{position:relative;z-index:1;background:#fff;border-radius:25px;overflow:hidden;border:1px solid rgba(15,76,35,.09);box-shadow:0 12px 35px rgba(15,76,35,.07);transform-style:preserve-3d;transition:transform .4s,box-shadow .4s}.neo-product:hover{transform:translateY(-10px) rotateX(2deg);box-shadow:0 28px 60px rgba(15,76,35,.16)}.neo-product-media{height:250px;position:relative;overflow:hidden;background:var(--neo-cream)}.neo-product-media:after{content:'';position:absolute;inset:0;background:linear-gradient(135deg,rgba(255,255,255,.22),transparent 50%);pointer-events:none}.neo-product-media img{width:100%;height:100%;object-fit:cover;transition:transform .7s}.neo-product:hover .neo-product-media img{transform:scale(1.08)}.neo-product-badge{position:absolute;top:15px;right:15px;z-index:2;padding:7px 12px;background:var(--neo-green);color:#fff;border-radius:99px;font-size:.78rem;font-weight:900;box-shadow:0 7px 18px rgba(15,76,35,.22)}.neo-product-info{padding:22px}.neo-product-cat{font-size:.82rem;color:var(--neo-secondary);font-weight:800}.neo-product-info h3{font-size:1.25rem;line-height:1.5;color:var(--neo-green);margin:8px 0 18px;font-weight:900}.neo-product-link{display:flex;align-items:center;justify-content:space-between;padding-top:14px;border-top:1px solid rgba(15,76,35,.1);color:var(--neo-green);font-weight:900}.neo-product-link i{font-style:normal;width:34px;height:34px;border-radius:11px;background:var(--neo-cream);display:grid;place-items:center;transition:.3s}.neo-product:hover .neo-product-link i{background:var(--neo-green);color:#fff;transform:translateX(-3px)}.neo-center{display:flex;justify-content:center;margin-top:42px}
/* brand statement */
.neo-story{background:var(--neo-green);color:#fff;overflow:hidden;isolation:isolate}.neo-story:before,.neo-story:after{content:'';position:absolute;border:1px solid rgba(255,255,255,.12);border-radius:50%;z-index:-1}.neo-story:before{width:650px;height:650px;left:-190px;top:-240px;box-shadow:0 0 0 55px rgba(255,255,255,.025),0 0 0 110px rgba(255,255,255,.02)}.neo-story:after{width:300px;height:300px;right:-120px;bottom:-140px}.neo-story-grid{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:70px}.neo-story-visual{min-height:430px;position:relative;perspective:1000px}.neo-story-image{position:absolute;inset:0 8% 0 8%;border-radius:35px;overflow:hidden;transform:rotateY(8deg) rotateX(2deg);box-shadow:0 30px 80px rgba(0,0,0,.28);border:1px solid rgba(255,255,255,.3)}.neo-story-image img{width:100%;height:100%;object-fit:cover}.neo-story-image:after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,rgba(15,76,35,.38),transparent 60%)}.neo-story-stamp{position:absolute;right:0;bottom:35px;background:var(--neo-accent);color:#182519;width:125px;height:125px;border-radius:50%;display:grid;place-items:center;text-align:center;font-weight:900;line-height:1.3;box-shadow:0 15px 35px rgba(0,0,0,.2);transform:rotate(-12deg);animation:orbFloat 6s infinite}.neo-story .neo-eyebrow{color:var(--neo-accent)}.neo-story h2{color:#fff;font-size:clamp(2.2rem,4.2vw,4rem);line-height:1.25;margin:0 0 22px;font-weight:900}.neo-story-copy{color:rgba(255,255,255,.78);font-size:1.08rem;line-height:2.1;margin:0 0 28px}.neo-story-points{display:grid;grid-template-columns:1fr 1fr;gap:17px;margin:30px 0}.neo-story-point{display:flex;align-items:center;gap:10px;font-weight:800}.neo-story-point b{width:29px;height:29px;display:grid;place-items:center;border-radius:10px;background:rgba(255,255,255,.12);color:var(--neo-accent)}
/* numbers */
.neo-numbers{background:#fff;padding:65px 0}.neo-number-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.neo-number{padding:26px;text-align:center;border-radius:22px;background:var(--neo-cream);border:1px solid rgba(15,76,35,.06);transition:transform .3s,box-shadow .3s}.neo-number:hover{transform:translateY(-7px);box-shadow:0 20px 35px rgba(15,76,35,.1)}.neo-number strong{display:block;font-size:clamp(2.5rem,4vw,3.5rem);color:var(--neo-green);font-weight:900;line-height:1.2}.neo-number span{color:var(--neo-muted);font-weight:800}
/* CTA */
.neo-cta-section{padding:100px 0;background:var(--neo-cream)}.neo-cta{position:relative;overflow:hidden;border-radius:34px;padding:clamp(35px,6vw,75px);background:linear-gradient(125deg,var(--neo-green),#0a3519);color:#fff;box-shadow:0 30px 70px rgba(15,76,35,.2);isolation:isolate}.neo-cta:after{content:'';position:absolute;width:370px;height:370px;left:-80px;top:-150px;border-radius:50%;border:1px solid rgba(255,255,255,.16);box-shadow:0 0 0 35px rgba(255,255,255,.035),0 0 0 70px rgba(255,255,255,.025);z-index:-1}.neo-cta-inner{display:flex;align-items:center;justify-content:space-between;gap:35px}.neo-cta h2{font-size:clamp(2rem,4vw,3.3rem);line-height:1.25;margin:0 0 15px;font-weight:900}.neo-cta p{max-width:650px;color:rgba(255,255,255,.78);line-height:1.9;margin:0}.neo-cta .neo-btn{flex-shrink:0}
/* reveal and motion */
.neo-reveal{opacity:0;transform:translateY(28px);transition:opacity .8s ease,transform .8s cubic-bezier(.2,.7,.2,1)}.neo-reveal.is-visible{opacity:1;transform:translateY(0)}@keyframes heroZoom{from{transform:scale(1.06)}to{transform:scale(1.17)}}@keyframes riseIn{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:translateY(0)}}@keyframes orbFloat{0%,100%{transform:translateY(0) rotate(0)}50%{transform:translateY(-16px) rotate(4deg)}}@keyframes cardLevitate{0%,100%{transform:rotateY(-12deg) rotateX(5deg) translateY(0)}50%{transform:rotateY(-8deg) rotateX(2deg) translateY(-12px)}}
@media(max-width:1000px){.neo-hero-inner{grid-template-columns:1fr .72fr;gap:20px}.neo-hero h1{font-size:clamp(2.6rem,6vw,4.5rem)}.neo-category-grid,.neo-product-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.neo-category{min-height:300px}.neo-story-grid{gap:35px}.neo-story-visual{min-height:360px}}
@media(max-width:760px){.container{width:min(100% - 28px,1220px)}.neo-nav-inner{min-height:72px}.neo-logo img{height:48px}.neo-menu{display:block}.neo-links{display:none;position:absolute;top:100%;right:14px;left:14px;background:#fff;padding:18px;border-radius:20px;box-shadow:0 20px 40px rgba(15,76,35,.16);flex-direction:column;align-items:stretch;gap:4px}.neo-links.open{display:flex}.neo-links a{padding:12px}.neo-nav-tools{gap:7px}.neo-lang{padding:9px 11px}.neo-hero{min-height:auto}.neo-hero-inner{grid-template-columns:1fr;padding-block:80px 95px;gap:32px}.neo-hero h1{font-size:clamp(2.6rem,12vw,4.2rem);letter-spacing:-.5px}.neo-hero-copy{font-size:1.03rem}.neo-hero-visual{min-height:330px;max-width:440px;width:100%;margin:auto}.neo-glass-card{width:65%;min-width:245px;max-width:310px;aspect-ratio:.9}.neo-orb.one{width:190px;height:190px;left:-10%;top:15%}.neo-orb.two{width:100px;height:100px;left:8%;bottom:5%}.neo-float-chip.top{right:0}.neo-float-chip.bottom{left:0}.neo-trust-wrap{margin-top:-22px}.neo-trust{grid-template-columns:1fr}.neo-trust-item{justify-content:flex-start;padding:15px 20px}.neo-trust-item+.neo-trust-item{border-right:0;border-top:1px solid rgba(15,76,35,.09)}.neo-section{padding:75px 0}.neo-section-head{align-items:flex-start;flex-direction:column;margin-bottom:30px}.neo-category-grid,.neo-product-grid{gap:13px}.neo-category{min-height:245px;border-radius:20px}.neo-category-content{padding:16px}.neo-category-content h3{font-size:1.2rem}.neo-product{border-radius:20px}.neo-product-media{height:190px}.neo-product-info{padding:15px}.neo-product-info h3{font-size:1.05rem}.neo-product-link{font-size:.9rem}.neo-story-grid{grid-template-columns:1fr;gap:38px}.neo-story-visual{min-height:340px;order:2}.neo-story-copy{font-size:1rem}.neo-story-points{gap:13px}.neo-number-grid{gap:10px}.neo-number{padding:20px 8px}.neo-number strong{font-size:2.2rem}.neo-number span{font-size:.85rem}.neo-cta-section{padding:65px 0}.neo-cta-inner{align-items:flex-start;flex-direction:column}.neo-cta{border-radius:26px}.neo-cta .neo-btn{width:100%}}
@media(max-width:420px){.neo-category-grid,.neo-product-grid{grid-template-columns:1fr}.neo-category{min-height:310px}.neo-product-media{height:245px}.neo-hero-actions{flex-direction:column}.neo-btn{width:100%}.neo-story-points{grid-template-columns:1fr}.neo-number-grid{grid-template-columns:1fr}.neo-number{display:flex;align-items:center;justify-content:center;gap:15px}.neo-number strong{font-size:2rem}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important;transition-duration:.01ms!important}.neo-reveal{opacity:1;transform:none}}

/* Fresh floating-produce atmosphere: keeps the original green/gold palette */
.neo-categories,.neo-products,.neo-numbers,.neo-cta-section{background-color:var(--neo-cream)!important;background-image:radial-gradient(ellipse at 12% 18%,rgba(46,125,69,.13),transparent 33%),radial-gradient(ellipse at 88% 78%,rgba(201,164,92,.12),transparent 30%),linear-gradient(135deg,rgba(255,255,255,.28),rgba(226,239,222,.46));}
.neo-products{background-image:radial-gradient(ellipse at 10% 22%,rgba(46,125,69,.13),transparent 32%),radial-gradient(ellipse at 90% 75%,rgba(201,164,92,.13),transparent 30%),linear-gradient(135deg,rgba(247,248,244,.94),rgba(226,239,222,.76))!important;}
.neo-story{background-image:radial-gradient(ellipse at 15% 25%,rgba(201,164,92,.14),transparent 28%),radial-gradient(ellipse at 85% 75%,rgba(255,255,255,.09),transparent 32%),linear-gradient(135deg,#0F4C23,#123f22)!important;}
.neo-section,.neo-numbers,.neo-cta-section{position:relative;isolation:isolate;overflow:hidden;}
.neo-section>.container,.neo-numbers>.container,.neo-cta-section>.container{position:relative;z-index:2;}
.neo-veggie-field{position:absolute;inset:0;overflow:hidden;pointer-events:none;z-index:1;perspective:900px;}
.neo-veggie-field span{position:absolute;display:block;font-size:clamp(3.8rem,7vw,6.8rem);line-height:1;opacity:.96;filter:drop-shadow(0 18px 13px rgba(15,45,20,.32));transform-style:preserve-3d;will-change:transform;animation:veggieFlight var(--duration,13s) ease-in-out infinite;animation-delay:var(--delay,0s);user-select:none;}
.neo-veggie-field span:nth-child(1){top:8%;left:4%;--duration:10s;--delay:-3s}
.neo-veggie-field span:nth-child(2){top:57%;left:15%;--duration:12s;--delay:-8s;font-size:clamp(3.2rem,6vw,5.6rem)}
.neo-veggie-field span:nth-child(3){top:20%;right:5%;--duration:11s;--delay:-6s}
.neo-veggie-field span:nth-child(4){top:68%;right:9%;--duration:13s;--delay:-10s;font-size:clamp(3.4rem,6vw,6rem)}
.neo-veggie-field span:nth-child(5){top:42%;left:47%;--duration:14s;--delay:-4s;font-size:clamp(3rem,5vw,4.8rem);opacity:.9}
.neo-veggie-field span:nth-child(6){top:10%;right:34%;--duration:12s;--delay:-2s;font-size:clamp(3rem,5vw,4.8rem)}
.neo-veggie-field span:nth-child(7){bottom:6%;left:38%;--duration:15s;--delay:-7s;font-size:clamp(3.2rem,6vw,5.8rem)}
.neo-veggie-field span:nth-child(8){top:38%;right:24%;--duration:13s;--delay:-5s;font-size:clamp(2.8rem,5vw,4.6rem)}
.neo-story .neo-veggie-field span{opacity:.9;filter:drop-shadow(0 18px 18px rgba(0,0,0,.28))}
