/* ==========================================
   MAIN INITIALIZATION
   ========================================== */

document.addEventListener("DOMContentLoaded", () => {
  let currentLang = document.documentElement.getAttribute("lang") || "ar";

  /* ------------------------------------------
     Language Switcher
     ------------------------------------------ */

  function initLanguageSwitcher() {
    const langSwitcher = document.getElementById("langSwitcher");

    if (!langSwitcher) return;

    langSwitcher.addEventListener("click", () => {
      currentLang = currentLang === "ar" ? "en" : "ar";

      document.documentElement.setAttribute("lang", currentLang);

      document.documentElement.setAttribute(
        "dir",
        currentLang === "ar" ? "rtl" : "ltr",
      );

      langSwitcher.textContent = currentLang === "ar" ? "English" : "العربية";

      updateTranslations();
    });
  }

  function updateTranslations() {
    document.querySelectorAll("[data-i18n]").forEach((element) => {
      const key = element.getAttribute("data-i18n");

      if (translations[currentLang] && translations[currentLang][key]) {
        element.textContent = translations[currentLang][key];
      }
    });
  }

  /* ==========================================
     HERO SLIDER
     ========================================== */

  function initHeroSlider() {
    const slides = document.querySelectorAll(".slide");

    const dots = document.querySelectorAll(".dot");

    const prevBtn = document.getElementById("prevSlide");

    const nextBtn = document.getElementById("nextSlide");

    if (!slides.length) return;

    let currentSlide = 0;

    let slideInterval;

    const intervalTime = 5000;

    function goToSlide(index) {
      slides[currentSlide].classList.remove("active");

      if (dots.length) {
        dots[currentSlide].classList.remove("active");
      }

      currentSlide = index;

      if (currentSlide >= slides.length) {
        currentSlide = 0;
      }

      if (currentSlide < 0) {
        currentSlide = slides.length - 1;
      }

      slides[currentSlide].classList.add("active");

      if (dots.length) {
        dots[currentSlide].classList.add("active");
      }
    }

    function nextSlide() {
      goToSlide(currentSlide + 1);
    }

    function previousSlide() {
      goToSlide(currentSlide - 1);
    }

    function startInterval() {
      slideInterval = setInterval(nextSlide, intervalTime);
    }

    function resetInterval() {
      clearInterval(slideInterval);
      startInterval();
    }

    if (nextBtn) {
      nextBtn.addEventListener("click", () => {
        nextSlide();
        resetInterval();
      });
    }

    if (prevBtn) {
      prevBtn.addEventListener("click", () => {
        previousSlide();
        resetInterval();
      });
    }

    dots.forEach((dot, index) => {
      dot.addEventListener("click", () => {
        goToSlide(index);
        resetInterval();
      });
    });

    startInterval();
  }

  /* ==========================================
     PRODUCTS FILTER
     ========================================== */

  function initProductsFilter() {
    const filterBtns = document.querySelectorAll(
      ".products-filter:not(.gallery-filter) .filter-btn",
    );

    const productCards = document.querySelectorAll(".product-card");

    if (!filterBtns.length) return;

    filterBtns.forEach((btn) => {
      btn.addEventListener("click", () => {
        filterBtns.forEach((button) => {
          button.classList.remove("active");
        });

        btn.classList.add("active");

        const filterValue = btn.getAttribute("data-filter");

        productCards.forEach((card) => {
          const category = card.getAttribute("data-category");

          if (filterValue === "all" || category === filterValue) {
            card.style.display = "block";

            requestAnimationFrame(() => {
              card.style.opacity = "1";
              card.style.transform = "translateY(0)";
            });
          } else {
            card.style.opacity = "0";

            card.style.transform = "translateY(10px)";

            setTimeout(() => {
              card.style.display = "none";
            }, 300);
          }
        });
      });
    });

    /* URL Category */

    const params = new URLSearchParams(window.location.search);

    const categoryParam = params.get("category");

    if (categoryParam) {
      const targetBtn = document.querySelector(
        `.products-filter:not(.gallery-filter) .filter-btn[data-filter="${categoryParam}"]`,
      );

      if (targetBtn) {
        targetBtn.click();
      }
    }
  }

  /* ==========================================
     PRODUCT DETAILS MODAL
     ========================================== */

  function initProductModal() {
    const productModal = document.getElementById("productModal");

    const closeBtn = document.querySelector(".close-product-modal");

    const detailButtons = document.querySelectorAll(".view-details-btn");

    if (!productModal || !detailButtons.length) {
      return;
    }

    function closeModal() {
      productModal.style.display = "none";

      document.body.style.overflow = "auto";
    }

    detailButtons.forEach((btn) => {
      btn.addEventListener("click", (event) => {
        const card = event.target.closest(".product-card");

        if (!card) return;

        const image = card.querySelector("img");

        const category = card.querySelector(".category-tag");

        const title = card.querySelector("h4");

        const details = card.querySelector(".product-details-data");

        const modalImage = document.getElementById("modalProductImg");

        const modalCategory = document.getElementById("modalProductCategory");

        const modalTitle = document.getElementById("modalProductTitle");

        const modalDetails = document.getElementById("modalProductDetails");

        if (modalImage && image) {
          modalImage.src = image.src;
        }

        if (modalCategory && category) {
          modalCategory.innerHTML = category.innerHTML;
        }

        if (modalTitle && title) {
          modalTitle.innerHTML = title.innerHTML;
        }

        if (modalDetails && details) {
          modalDetails.innerHTML = details.innerHTML;
        }

        productModal.style.display = "block";

        document.body.style.overflow = "hidden";
      });
    });

    if (closeBtn) {
      closeBtn.addEventListener("click", closeModal);
    }

    productModal.addEventListener("click", (event) => {
      if (event.target === productModal) {
        closeModal();
      }
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && productModal.style.display === "block") {
        closeModal();
      }
    });
  }

  /* ==========================================
     PREMIUM MASONRY GALLERY
     ========================================== */

  function initGallery() {
    const galleryWrapper = document.getElementById("galleryWrapper");

    if (!galleryWrapper) return;

    const items = Array.from(galleryWrapper.querySelectorAll(".masonry-item"));

    const filterBtns = document.querySelectorAll(".gallery-filter .filter-btn");

    const lightbox = document.getElementById("lightbox");

    const lightboxImg = document.getElementById("lightbox-img");

    const lightboxCaption = document.getElementById("lightbox-caption");

    const closeBtn = document.querySelector(".lightbox-close");

    if (!items.length) return;

    let currentLightboxIndex = -1;

    /* ------------------------------------------
       3D Tilt
       ------------------------------------------ */

    const enableTilt = window.matchMedia(
      "(hover: hover) and (pointer: fine)",
    ).matches;

    if (enableTilt) {
      items.forEach((item) => {
        item.addEventListener("mousemove", (event) => {
          const rect = item.getBoundingClientRect();

          const x = event.clientX - rect.left;

          const y = event.clientY - rect.top;

          const centerX = rect.width / 2;

          const centerY = rect.height / 2;

          const rotateX = ((y - centerY) / centerY) * -3;

          const rotateY = ((x - centerX) / centerX) * 3;

          item.style.transform = `perspective(900px)
               rotateX(${rotateX}deg)
               rotateY(${rotateY}deg)
               translateY(-4px)
               scale(1.015)`;
        });

        item.addEventListener("mouseleave", () => {
          item.style.transform =
            "perspective(900px) rotateX(0deg) rotateY(0deg) translateY(0) scale(1)";
        });
      });
    }

    /* ------------------------------------------
       Filtering
       ------------------------------------------ */

    filterBtns.forEach((btn) => {
      btn.addEventListener("click", () => {
        filterBtns.forEach((button) => {
          button.classList.remove("active");
        });

        btn.classList.add("active");

        const filter = btn.getAttribute("data-filter");

        items.forEach((item) => {
          const category = item.getAttribute("data-category");

          const shouldShow = filter === "all" || category === filter;

          if (shouldShow) {
            item.style.display = "inline-block";

            requestAnimationFrame(() => {
              item.style.opacity = "1";

              item.style.transform = "translateY(0) scale(1)";
            });
          } else {
            item.style.opacity = "0";

            item.style.transform = "translateY(15px) scale(.94)";

            setTimeout(() => {
              item.style.display = "none";
            }, 400);
          }
        });
      });
    });

    /* ------------------------------------------
       Get Visible Items
       ------------------------------------------ */

    function getVisibleItems() {
      return items.filter((item) => item.style.display !== "none");
    }

    /* ------------------------------------------
       Open Lightbox
       ------------------------------------------ */

    function openLightbox(item) {
      if (!lightbox || !lightboxImg) {
        return;
      }

      const visibleItems = getVisibleItems();

      currentLightboxIndex = visibleItems.indexOf(item);

      const image = item.querySelector("img");

      const title = item.querySelector(".masonry-title");

      if (!image) return;

      lightboxImg.src = image.src;

      lightboxImg.alt = image.alt || "";

      if (lightboxCaption) {
        lightboxCaption.innerHTML = title ? title.innerHTML : "";
      }

      lightbox.style.display = "flex";

      requestAnimationFrame(() => {
        lightbox.style.opacity = "1";
      });

      document.body.style.overflow = "hidden";
    }

    /* ------------------------------------------
       Close Lightbox
       ------------------------------------------ */

    function closeLightbox() {
      if (!lightbox) return;

      lightbox.style.opacity = "0";

      setTimeout(() => {
        lightbox.style.display = "none";

        document.body.style.overflow = "auto";
      }, 300);
    }

    /* ------------------------------------------
       Navigate Lightbox
       ------------------------------------------ */

    function navigateLightbox(direction) {
      const visibleItems = getVisibleItems();

      if (!visibleItems.length) {
        return;
      }

      currentLightboxIndex += direction;

      if (currentLightboxIndex < 0) {
        currentLightboxIndex = visibleItems.length - 1;
      }

      if (currentLightboxIndex >= visibleItems.length) {
        currentLightboxIndex = 0;
      }

      openLightbox(visibleItems[currentLightboxIndex]);
    }

    /* ------------------------------------------
       Item Click
       ------------------------------------------ */

    items.forEach((item) => {
      item.addEventListener("click", () => {
        openLightbox(item);
      });
    });

    /* ------------------------------------------
       Close
       ------------------------------------------ */

    if (closeBtn) {
      closeBtn.addEventListener("click", (event) => {
        event.stopPropagation();

        closeLightbox();
      });
    }

    if (lightbox) {
      lightbox.addEventListener("click", (event) => {
        if (event.target === lightbox) {
          closeLightbox();
        }
      });
    }

    /* ------------------------------------------
       Keyboard
       ------------------------------------------ */

    document.addEventListener("keydown", (event) => {
      if (!lightbox || lightbox.style.display !== "flex") {
        return;
      }

      switch (event.key) {
        case "Escape":
          closeLightbox();
          break;

        case "ArrowRight":
          if (document.documentElement.dir === "rtl") {
            navigateLightbox(-1);
          } else {
            navigateLightbox(1);
          }

          break;

        case "ArrowLeft":
          if (document.documentElement.dir === "rtl") {
            navigateLightbox(1);
          } else {
            navigateLightbox(-1);
          }

          break;
      }
    });

    /* ------------------------------------------
       Touch Swipe
       ------------------------------------------ */

    let touchStartX = 0;

    if (lightbox) {
      lightbox.addEventListener(
        "touchstart",
        (event) => {
          touchStartX = event.changedTouches[0].screenX;
        },
        {
          passive: true,
        },
      );

      lightbox.addEventListener(
        "touchend",
        (event) => {
          const touchEndX = event.changedTouches[0].screenX;

          const difference = touchEndX - touchStartX;

          if (Math.abs(difference) < 50) {
            return;
          }

          if (difference < 0) {
            navigateLightbox(1);
          } else {
            navigateLightbox(-1);
          }
        },
        {
          passive: true,
        },
      );
    }
  }

  /* ==========================================
     CONTACT FORM
     ========================================== */

  function initContactForm() {
    const contactForm = document.getElementById("contactForm");

    const formMessage = document.getElementById("formMessage");

    if (!contactForm || !formMessage) {
      return;
    }

    contactForm.addEventListener("submit", async (event) => {
      event.preventDefault();

      const formData = new FormData(contactForm);

      const submitButton = contactForm.querySelector(
        'button[type="submit"], input[type="submit"]',
      );

      if (submitButton) {
        submitButton.disabled = true;
      }

      try {
        const response = await fetch("api/submit_contact.php", {
          method: "POST",
          body: formData,
        });

        if (!response.ok) {
          throw new Error(`HTTP Error: ${response.status}`);
        }

        const data = await response.json();

        if (data.status === "success") {
          formMessage.textContent =
            translations[currentLang]?.msg_success ||
            "Thank you! Your message has been sent successfully.";

          formMessage.classList.remove("hidden", "error");

          formMessage.classList.add("success");

          contactForm.reset();
        } else {
          formMessage.textContent =
            data.message ||
            (currentLang === "ar"
              ? "حدث خطأ أثناء إرسال الرسالة."
              : "Error sending message.");

          formMessage.classList.remove("hidden", "success");

          formMessage.classList.add("error");
        }

        setTimeout(() => {
          formMessage.classList.add("hidden");

          formMessage.classList.remove("success", "error");
        }, 5000);
      } catch (error) {
        console.error("Contact form error:", error);

        formMessage.textContent =
          currentLang === "ar"
            ? "حدث خطأ أثناء إرسال الرسالة. يرجى المحاولة مرة أخرى."
            : "An error occurred while sending the message. Please try again.";

        formMessage.classList.remove("hidden", "success");

        formMessage.classList.add("error");
      } finally {
        if (submitButton) {
          submitButton.disabled = false;
        }
      }
    });
  }

  /* ==========================================
     START EVERYTHING
     ========================================== */

  initLanguageSwitcher();

  initHeroSlider();

  initProductsFilter();

  initProductModal();

  initGallery();

  initContactForm();
});

/* ==========================================
   PRELOADER
   ========================================== */

(function () {
  function hidePreloader() {
    const preloader = document.getElementById("preloader");
    if (!preloader || preloader.dataset.hidden) return;
    preloader.dataset.hidden = "1";
    preloader.style.opacity = "0";
    preloader.style.pointerEvents = "none";
    setTimeout(() => {
      preloader.style.display = "none";
    }, 300);
  }
  // Hide as soon as the DOM is ready; hard limit as a fallback.
  document.addEventListener("DOMContentLoaded", hidePreloader);
  window.addEventListener("load", hidePreloader);
  setTimeout(hidePreloader, 1200);
})();
